 if(id==='camera'){const label=make('label','选择一张照片');label.style.cssText='display:block;padding:25px;text-align:center;background:#ede6f5;border-radius:20px';const input=make('input');input.type='file';input.accept='image/*';input.style.display='block';input.style.marginTop='20px';label.append(input);container.append(label);input.addEventListener('change',()=>{if(!input.files?.[0])return;const img=make('img');img.src=URL.createObjectURL(input.files[0]);img.style.cssText='width:100%;border-radius:20px;margin-top:18px';container.append(img);});return;}
